def transform(grid):
    # move each 4-connected color object right until blocked by boundary or another object
    h,w=len(grid),len(grid[0]); a=[r[:] for r in grid]
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
       if a[r][c] and (r,c) not in seen:
        col=a[r][c]; st=[(r,c)]; seen.add((r,c)); pts=[]
        while st:
         y,x=st.pop(); pts.append((y,x))
         for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
          if 0<=yy<h and 0<=xx<w and a[yy][xx]==col and (yy,xx) not in seen: seen.add((yy,xx));st.append((yy,xx))
        comps.append((col,pts))
    # rightmost first, then advance each entire component as far as possible
    comps.sort(key=lambda cp:max(x for y,x in cp[1]), reverse=True)
    out=[[0]*w for _ in range(h)]
    for col,pts in comps:
      d=0
      while True:
       nd=d+1
       if any(x+nd>=w or (out[y][x+nd] and (y,x+nd) not in {(yy,xx+nd-1) for yy,xx in []}) for y,x in pts): break
       # collisions against this component's current cells are fine; only check next shift against original component positions
       if any(out[y][x+nd] for y,x in pts if (y,x+nd) not in pts): break
       d=nd
      for y,x in pts: out[y][x+d]=col
    return out
